package com.logatron.audit.persistence;
import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.Instant;import java.util.*;
@Entity @Table(name="audit_event") public class AuditEventEntity{
 @Id private UUID id;@Column(name="actor_user_id") private UUID actorUserId;@Column(name="actor_subject",nullable=false,length=255) private String actorSubject;@Column(nullable=false,length=100) private String action;@Column(name="resource_type",nullable=false,length=80) private String resourceType;@Column(name="resource_id") private UUID resourceId;@Column(name="project_id") private UUID projectId;@Column(name="environment_id") private UUID environmentId;@Column(nullable=false,length=20) private String outcome;@Column(name="occurred_at",nullable=false) private Instant occurredAt;@Column(name="trace_id",length=64) private String traceId;@Column(name="client_ip",length=45) private String clientIp;@Column(name="user_agent",length=500) private String userAgent;@JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") private Map<String,String> metadata;
 protected AuditEventEntity(){}public AuditEventEntity(UUID actorUserId,String actorSubject,String action,String resourceType,UUID resourceId,UUID projectId,UUID environmentId,String outcome,String traceId,String clientIp,String userAgent,Map<String,String> metadata){id=UUID.randomUUID();this.actorUserId=actorUserId;this.actorSubject=actorSubject;this.action=action;this.resourceType=resourceType;this.resourceId=resourceId;this.projectId=projectId;this.environmentId=environmentId;this.outcome=outcome;this.occurredAt=Instant.now();this.traceId=traceId;this.clientIp=clientIp;this.userAgent=userAgent;this.metadata=metadata==null?Map.of():Map.copyOf(metadata);}
 public UUID getId(){return id;}public String getAction(){return action;}public String getOutcome(){return outcome;}
}
